import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.20 released — Streaming 深化 (Kafka + Redpanda + NATS の 5 semantics 統一 mock)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.20/gh-discussions-announcement.md","filePath":"announcements/v1.20/gh-discussions-announcement.md"}'),s={name:"announcements/v1.20/gh-discussions-announcement.md"};function i(c,e,n,d,l,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="kiwa-v1-20-released-—-streaming-深化-kafka-redpanda-nats-の-5-semantics-統一-mock" tabindex="-1">kiwa v1.20 released — Streaming 深化 (Kafka + Redpanda + NATS の 5 semantics 統一 mock) <a class="header-anchor" href="#kiwa-v1-20-released-—-streaming-深化-kafka-redpanda-nats-の-5-semantics-統一-mock" aria-label="Permalink to &quot;kiwa v1.20 released — Streaming 深化 (Kafka + Redpanda + NATS の 5 semantics 統一 mock)&quot;">​</a></h1><p>v1.20 is out. After v1.19&#39;s Framework 深化 horizontal (three modern web framework testing adapters — SolidJS Signal reactivity + Deno Fresh Islands + HonoJS Cloudflare Workers), v1.20 turns to the <strong>event-driven backbone</strong> — Kafka (kafkajs-shaped producer / consumer / admin), Redpanda (Kafka API 互換 broker + colocated schema registry), and NATS (core pub/sub + JetStream + KV / Object store) — one new package that lifts kiwa runtime fixture count from <strong>33 to 34</strong> while covering <strong>five broker semantics</strong> in a single mock surface.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-test/streaming</code> v0.1.0</strong> (new package). Unified Kafka + Redpanda + NATS testing mock covering the five streaming semantics production teams hit — producer, consumer, exactly-once, DLQ, schema registry — in one API surface. <code>createKafkaMock({ defaultPartitionCount })</code> returns a broker + producer + consumer + admin trio that mirrors <code>kafkajs</code> shape; deterministic djb2-style key-hash partitioner, per-partition offset log, and <code>partitionAssigner: &#39;range&#39; | &#39;round-robin&#39;</code> consumer groups. <code>createRedpandaMock({ schemaRegistry: true })</code> layers a colocated <code>SchemaRegistry</code> on top of a Kafka-shaped broker — <code>registerAvro</code> / <code>registerProtobuf</code> / <code>registerJson</code>, three compatibility modes (<code>BACKWARD</code> / <code>FORWARD</code> / <code>FULL</code>), schema evolution, and fail-fast publish gating. <code>createNatsMock()</code> gives core pub/sub with <code>*</code> (single-token) + <code>&gt;</code> (trailing multi-token) subject routing, <code>nats.jetstream()</code> persistent streams + consumers + ack tracking, and <code>js.kv(&#39;bucket&#39;)</code> / <code>js.objectStore(&#39;bucket&#39;)</code> that ride on the JetStream substrate. <code>createTransactionalProducer</code> + <code>createIdempotentProducer</code> + <code>createReadCommittedFilter</code> cover the Kafka exactly-once pillars (per-partition sequence dedup, multi-record atomic commit + abort, uncommitted-transaction filter). <code>createDeadLetterQueue</code> covers retry policy (max retries + backoff exponent) + poison message quarantine + inspect + reprocess flow. 104 behavior tests pass across <code>kafka.test.ts</code> + <code>redpanda.test.ts</code> + <code>nats.test.ts</code> + <code>exactly-once.test.ts</code> + <code>dlq.test.ts</code> + <code>schema-registry.test.ts</code> + <code>docs-tutorial-v1.20.test.ts</code>. Pure TypeScript — no Docker, Zookeeper, JVM, or a <code>nats-server</code> binary needed at test time.</li><li><strong><code>examples/dogfood-kafka-event-pipeline</code></strong> — Kafka producer + consumer group + exactly-once transactional producer + DLQ. <code>makeMockAdapter</code> uses <code>@kiwa-test/streaming</code> <code>createKafkaMock</code> + <code>createTransactionalProducer</code> + <code>createDeadLetterQueue</code>; <code>makeRealAdapter</code> wraps a Kafka-like harness. <code>KafkaFidelityReport</code> compares mock vs real behavior across 5 scenarios (partitioner determinism / consumer group rebalance / offset commit + seek / transactional producer atomic commit / DLQ retry exhaustion + quarantine). 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-redpanda-schema-registry</code></strong> — Redpanda + Avro schema registry + evolution + BACKWARD / FORWARD / FULL compatibility check. Ships 3 Avro schemas that stress each compatibility mode (v1 → v2 additive field / v2 → v3 breaking field type change / v3 → v4 default-value drop). <code>RedpandaFidelityReport</code> compares mock vs real behavior across 5 scenarios (schema register + fetch / evolution + version bump / compatibility gate pass + fail / fail-fast publish rejection / Kafka API round-trip on the same broker). 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-nats-jetstream</code></strong> — NATS core pub/sub + <code>*</code> / <code>&gt;</code> subject routing + JetStream persistent stream + KV Store + Object Store. <code>makeMockAdapter</code> uses <code>@kiwa-test/streaming</code> <code>createNatsMock</code> + <code>nats.jetstream()</code> + <code>js.kv</code> + <code>js.objectStore</code>; <code>makeRealAdapter</code> boots a minimal NATS-shaped runtime. <code>NatsFidelityReport</code> compares mock vs real behavior across 5 scenarios (core pub/sub / wildcard routing (<code>*</code> single-token + <code>&gt;</code> trailing multi-token) / JetStream persistent stream + consumer ack / KV round-trip / Object store round-trip). 7-axis release gate verdict PASS.</li><li><strong>docs</strong> — 3 new tutorials (31 Kafka event pipeline + producer + consumer group + exactly-once + DLQ / 32 Redpanda + schema registry + Avro schemas + evolution + compatibility / 33 NATS JetStream + persistent stream + KV + Object store + subject routing) + additive migration guide v1.19 → v1.20 + concept doc <code>streaming-testing.md</code> documenting the <strong>five semantics × six semantic axes</strong> (producer (partition + serialization + batch) / consumer (group + offset + rebalance) / exactly-once (transactional + idempotent + read-committed) / DLQ (retry policy + poison quarantine) / schema registry (Avro / Protobuf / JSON + compatibility gate + evolution)) as the SSOT. VitePress sidebar refreshed with a new <code>Streaming 深化 (v1.20)</code> tutorial section; gh-pages published via <code>/docs-publish-kiwa</code>.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#827-#832)</li><li><strong>6 PRs merged</strong> (v1.20-1 + v1.20-2/3/4/5 + this publish PR)</li><li><strong>1 new npm package</strong> (<code>@kiwa-test/streaming</code> v0.1.0) — kiwa runtime fixture count now <strong>34</strong></li><li><strong>3 new dogfood apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>104 new tests</strong> across the streaming package all pass</li></ul><h2 id="_10-milestone-streak" tabindex="-1">10-milestone streak <a class="header-anchor" href="#_10-milestone-streak" aria-label="Permalink to &quot;10-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → v1.19 (Framework 深化) → <strong>v1.20 (Streaming 深化)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100% milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>Auth depth (WebAuthn / Passkey / OAuth 2.1 / OIDC)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li></ul><p>Feedback welcome on which of these should land next.</p>',11)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
